using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<ModelTrainingService>();

var app = builder.Build();

// Train the model at startup so the prediction pool has a model to load
var trainingService = app.Services.GetRequiredService<ModelTrainingService>();
trainingService.TrainAndEvaluate();

app.Services.GetRequiredService<Microsoft.Extensions.Options.IOptionsMonitor<Microsoft.Extensions.ML.PredictionEnginePoolOptions<TicketInput, TicketPrediction>>>();

app.MapControllers();
